export async function imageCanvas(file,max=1800){if(!file||file.size>25e6)throw Error('Choose an image smaller than 25 MB.');let source,release=()=>{};try{source=await createImageBitmap(file);}catch{const url=URL.createObjectURL(file);source=new Image();release=()=>URL.revokeObjectURL(url);try{await new Promise((resolve,reject)=>{source.onload=resolve;source.onerror=()=>reject(Error('This photo format could not be read. Use a JPEG photo.'));source.src=url;});}catch(e){release();throw e;}}const w=source.width||source.naturalWidth,h=source.height||source.naturalHeight,scale=Math.min(1,max/Math.max(w,h)),canvas=document.createElement('canvas');canvas.width=Math.round(w*scale);canvas.height=Math.round(h*scale);canvas.getContext('2d').drawImage(source,0,0,canvas.width,canvas.height);source.close?.();release();return canvas;}
export async function storedPhoto(file){const canvas=await imageCanvas(file);try{const data=canvas.toDataURL('image/jpeg',.82);if(data.length>4e6)throw Error('This photo is too large to save. Try a closer photograph.');return {data,type:'image/jpeg',capturedAt:new Date().toISOString(),width:canvas.width,height:canvas.height};}finally{canvas.width=0;canvas.height=0;}}
export function photoFile(photo,name){const [meta,body]=photo.data.split(',');const bytes=Uint8Array.from(atob(body),c=>c.charCodeAt(0));return new File([bytes],name,{type:photo.type||'image/jpeg'});}
export function cateringFiles(delivery){return ['setup','receipt'].filter(k=>delivery.cateringPhotos?.[k]).map(k=>photoFile(delivery.cateringPhotos[k],`catering-${delivery.id}-${k}.jpg`));}
